  var idx={en:0,ja:1};
  var items=[];
  var seen=(typeof WeakSet!=='undefined')?new WeakSet():null;   // 已登記的文字節點（重複掃描時去重）
  var seenAttr=(typeof WeakMap!=='undefined')?new WeakMap():null; // 已登記的屬性
  function reg(node,type,attr,zh){
    if(type==='text'){ if(seen){ if(seen.has(node)) return; seen.add(node); } }
    else if(seenAttr){ var m=seenAttr.get(node)||{}; if(m[attr]) return; m[attr]=1; seenAttr.set(node,m); }
    items.push({node:node,type:type,attr:attr,zh:zh,key:zh.trim()});
  }
  function collect(){
    var w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,null,false),n;
    while(n=w.nextNode()){
      var p=n.parentNode; if(!p) continue;
      if(p.closest&&p.closest('script,style,noscript')) continue;
      var z=n.nodeValue; if(z&&z.trim()&&T[z.trim()]) reg(n,'text',null,z);
    }
    ['placeholder','aria-label','title','alt'].forEach(function(a){
      Array.prototype.forEach.call(document.querySelectorAll('['+a+']'),function(el){
        var v=el.getAttribute(a); if(v&&T[v.trim()]) reg(el,'attr',a,v);
      });
    });
  }
  function apply(lang){
    for(var i=0;i<items.length;i++){
      var it=items[i];
      var tr = lang==='zh' ? it.key : (T[it.key]?T[it.key][idx[lang]]:null);
      if(tr==null) tr=it.key;
      var val=it.zh.replace(it.key,tr);
      if(it.type==='text') it.node.nodeValue=val; else it.node.setAttribute(it.attr,val);
    }
    document.documentElement.lang = lang==='zh'?'zh-Hant':lang;
    try{localStorage.setItem('ms_lang',lang);}catch(e){}
    var a=document.querySelectorAll('.langsw a');
    for(var j=0;j<a.length;j++) a[j].className=(a[j].getAttribute('data-l')===lang?'cur':'');
    var lm=document.getElementById('langMenu'); if(lm) lm.classList.remove('open');
    CUR=lang;
  }
  /* ===== 動態內容自動翻譯（2026-08-07）=====
   * 問題：collect() 只在開頁時跑一次，之後由 JS 產生的內容（會議室預約日曆、線上客服泡泡、
   *       任何 innerHTML 塞進來的區塊）永遠不會被翻譯 → 英/日版出現中文。
   * 解法：用 MutationObserver 監看 DOM，有新內容就重新掃描並套用目前語言。
   *       reg() 已去重，重掃不會重複登記；apply() 以原始中文 it.zh 為基準，重複套用不會壞。 */
  var CUR='zh', busy=false, tid=null;
  function refresh(){
    if(CUR==='zh') return;   // 中文訪客不需要任何替換，直接略過（避免無謂的重掃）
    if(busy) return; busy=true;
    try{ collect(); apply(CUR); }catch(e){}
    setTimeout(function(){ busy=false; },0);
  }
  window.msI18nRefresh=refresh;      // 需要時可由其他程式主動呼叫
  function watch(){
    if(typeof MutationObserver==='undefined') return;
    new MutationObserver(function(){
      if(busy) return;
      clearTimeout(tid); tid=setTimeout(refresh,120);   // 合併連續變動，避免頻繁重掃
    }).observe(document.body,{childList:true,subtree:true,characterData:true});
  }
  /* ⚠️ 2026-11-03 修正：以下字典區塊原本被包在 watch() 函式裡（9/2 起的新增都誤放在 watch 結尾大括號之前），
   *    要等 watch() 執行（開頁翻譯之後）才載入 → 回訪的英/日訪客開頁時這 111 句維持中文。
   *    新增字典一律放在函式外（本行以下或 T 定義區），工具_多語覆蓋率檢查.js 會實際執行驗證。 */
